282:   282	                throw e;
283:   283	            }
284:   284	            log.error("주문 입찰 삭제 중 오류 발생: {}", e.getMessage(), e);
285:   285	            throw new OrderBidDeletionFailedException("주문 입찰 삭제 중 오류가 발생했습니다: " + e.getMessage(), e);
286:   286	        }
