171:   171	     */
172:   172	    private SaleBid getSaleBidAndValidate(Long saleBidId) {
173:   173	        SaleBid saleBid = saleBidQueryService.findById(saleBidId);
174:   174	        if (saleBid == null) {
175:   175	            throw new SaleBidNotFoundException("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
176:   176	        }
177:   177	
178:   178	        Sale sale = saleBid.getSale();
179:   179	        if (sale == null) {
180:   180	            throw new InvalidOrderBidDataException("판매 입찰과 연결된 판매 정보가 없습니다.");
