213:   213	        if (e instanceof OrderException) {
214:   214	            throw (OrderException) e;
215:   215	        }
216:   216	        log.error("{} 중 오류 발생: {}", operation, e.getMessage(), e);
217:   217	        throw new OrderBidCreationFailedException(operation + " 중 오류가 발생했습니다: " + e.getMessage(), e);
218:   218	    }
219:   219	
220:   220	    /**
221:   221	     * 주문 입찰을 매칭 상태로 업데이트합니다.
222:   222	     *
223:   223	     * @param orderBid 주문 입찰
224:   224	     * @throws InvalidOrderBidStatusException 주문 입찰 상태가 유효하지 않은 경우
225:   225	     * @throws OrderBidMatchingFailedException 주문 입찰 매칭 실패 시
226:   226	     */
227:   227	    @Transactional
228:   228	    public void matchOrderBid(OrderBid orderBid) {
229:   229	        try {
230:   230	            if (orderBid == null) {
231:   231	                throw new OrderBidNotFoundException("주문 입찰 정보가 없습니다.");
232:   232	            }
233:   233	
234:   234	            if (orderBid.getStatus() == BidStatus.MATCHED) {
235:   235	                throw new OrderBidAlreadyMatchedException("이미 매칭된 주문 입찰입니다(ID: " + orderBid.getId() + ")");
236:   236	            }
237:   237	
238:   238	            orderBid.updateStatus(BidStatus.MATCHED);
239:   239	        } catch (Exception e) {
240:   240	            if (e instanceof OrderException) {
241:   241	                throw e;
242:   242	            }
243:   243	            log.error("주문 입찰 매칭 중 오류 발생: {}", e.getMessage(), e);
244:   244	            throw new OrderBidMatchingFailedException("주문 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
245:   245	        }
246:   246	    }
247:   247	
248:   248	    /**
249:   249	     * 주문 입찰을 삭제합니다.
250:   250	     *
251:   251	     * @param orderBidId 주문 입찰 ID
252:   252	     * @throws OrderBidNotFoundException 주문 입찰을 찾을 수 없는 경우
253:   253	     * @throws OrderBidAlreadyMatchedException 이미 매칭된 주문 입찰인 경우
254:   254	     * @throws OrderBidDeletionFailedException 주문 입찰 삭제 실패 시
255:   255	     */
256:   256	    @Transactional
257:   257	    public void deleteOrderBid(Long orderBidId) {
258:   258	        try {
259:   259	            // OrderBid 조회
260:   260	            OrderBid orderBid = orderBidRepository.findById(orderBidId)
261:   261	                    .orElseThrow(() -> new OrderBidNotFoundException("해당 주문 입찰을 찾을 수 없습니다(ID: " + orderBidId + ")"));
262:   262	
263:   263	            // Sale과 연결 여부 확인
264:   264	            if (orderBid.getSale() != null) {
265:   265	                throw new OrderBidAlreadyMatchedException("주문 입찰이 판매와 연결되어 있어 삭제할 수 없습니다.");
266:   266	            }
267:   267	
268:   268	            // 매칭 상태 확인
269:   269	            if (orderBid.getStatus() == BidStatus.MATCHED) {
270:   270	                throw new OrderBidAlreadyMatchedException("이미 매칭된 주문 입찰은 삭제할 수 없습니다.");
271:   271	            }
272:   272	
273:   273	            // Order와 연결 여부 확인 후 삭제
274:   274	            if (orderBid.getOrder() != null) {
275:   275	                orderCommandService.deleteOrder(orderBid.getOrder().getId());
276:   276	            }
277:   277	
278:   278	            // OrderBid 삭제
279:   279	            orderBidRepository.delete(orderBid);
280:   280	        } catch (Exception e) {
281:   281	            if (e instanceof OrderException) {
282:   282	                throw e;
283:   283	            }
284:   284	            log.error("주문 입찰 삭제 중 오류 발생: {}", e.getMessage(), e);
285:   285	            throw new OrderBidDeletionFailedException("주문 입찰 삭제 중 오류가 발생했습니다: " + e.getMessage(), e);
286:   286	        }
287:   287	    }

